     1	/**
     2	 * An item a policy covers, as the office records it.
     3	 *
     4	 * The office reads the recorded facts to classify the item's risk, so the
     5	 * classifications live here with the facts they read, while what each risk
     6	 * costs is the premium rules' business in {@link PremiumPolicy}. The
     7	 * enchantment level carries more than one such classification: the premium
     8	 * rules surcharge a high enchantment from level 5 up, and the claim rules have
     9	 * their own, higher threshold, so each threshold is named for the rule it
    10	 * serves rather than sharing one vague "enchanted" predicate.
    11	 */
    12	public record InsuredItem(String type, boolean cursed, int enchantment) {
    13	
    14	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    15	    private static final int UNRULY_ENCHANTMENT_LEVEL = 8;
    16	
    17	    /**
    18	     * The office counts an item as highly enchanted, and so as carrying a risk
    19	     * worth a surcharge, from enchantment level 5 up.
    20	     */
    21	    public boolean isHighlyEnchanted() {
    22	        return enchantment >= HIGH_ENCHANTMENT_LEVEL;
    23	    }
    24	
    25	    /**
    26	     * From enchantment level 8 up the office considers an item too unruly for
    27	     * its damage to be reimbursed in full. What such a damage earns instead is
    28	     * the claim rules' clause to state, in {@link ClaimPolicy}.
    29	     */
    30	    public boolean isTooUnrulyToReimburseInFull() {
    31	        return enchantment >= UNRULY_ENCHANTMENT_LEVEL;
    32	    }
    33	}
===== PayoutCap =====
     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The limit on everything a policy will ever pay out, and how much of it is
     5	 * left. The office caps a policy at twice the insurance sum of the items it
     6	 * covers.
     7	 *
     8	 * What the cap is worth and what it has left are one decision revised on its
     9	 * own schedule: a revision to the multiple, or one that let the cap replenish,
    10	 * is this cap's business and touches no claim rule. Premium modifiers are no
    11	 * part of it, which is why a cap is opened from an insurance sum and never from
    12	 * a premium.
    13	 */
    14	class PayoutCap {
    15	
    16	    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");
    17	
    18	    private BigDecimal remaining;
    19	
    20	    static PayoutCap forInsuranceSum(BigDecimal insuranceSum) {
    21	        return new PayoutCap(insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM));
    22	    }
    23	
    24	    private PayoutCap(BigDecimal remaining) {
    25	        this.remaining = remaining;
    26	    }
    27	
    28	    /** Pays what the cap still allows of a desired payout and consumes that much of it. */
    29	    BigDecimal pay(BigDecimal desiredPayout) {
    30	        BigDecimal paid = desiredPayout.min(remaining);
    31	        remaining = remaining.subtract(paid);
    32	        return paid;
    33	    }
    34	
    35	    BigDecimal remaining() {
    36	        return remaining;
    37	    }
    38	}
